-- ICFR O2C AUDIT TESTING ENGINE — INITIAL DATABASE SCHEMA
create table if not exists customers (customer_id bigint generated by default as identity primary key, customer_name text not null, created_at timestamptz default now());
create table if not exists sales_transactions (transaction_id bigint generated by default as identity primary key, customer_id bigint references customers(customer_id), invoice_id text, transaction_date date, transaction_time time, guest_name text, revenue_type text, taxable_amount numeric(18,2), cgst numeric(18,2) default 0, sgst numeric(18,2) default 0, igst numeric(18,2) default 0, total_amount numeric(18,2), payment_mode text, created_at timestamptz default now());
create table if not exists invoices (invoice_id bigint generated by default as identity primary key, invoice_number text unique, invoice_date date, customer_id bigint references customers(customer_id), guest_name text, gstin text, taxable_amount numeric(18,2), cgst numeric(18,2) default 0, sgst numeric(18,2) default 0, igst numeric(18,2) default 0, total_amount numeric(18,2), invoice_file_path text, extraction_status text default 'PENDING', created_at timestamptz default now());
create table if not exists payments (payment_id bigint generated by default as identity primary key, transaction_id bigint references sales_transactions(transaction_id), customer_id bigint references customers(customer_id), payment_date date, payment_time time, payment_mode text, amount numeric(18,2), payment_reference text, created_at timestamptz default now());
create table if not exists bank_transactions (bank_transaction_id bigint generated by default as identity primary key, transaction_date date, transaction_time time, value_date date, reference text, narration text, debit numeric(18,2) default 0, credit numeric(18,2) default 0, balance numeric(18,2), created_at timestamptz default now());
create table if not exists controls (control_id bigint generated by default as identity primary key, control_code text, process text, risk text, control_objective text, control_description text, test_logic text, created_at timestamptz default now());
create table if not exists audit_samples (sample_id bigint generated by default as identity primary key, sample_reference text unique, transaction_id bigint references sales_transactions(transaction_id), invoice_number text, amount numeric(18,2), customer_name text, guest_name text, status text default 'PENDING', created_at timestamptz default now());
create table if not exists control_tests (test_id bigint generated by default as identity primary key, sample_id bigint references audit_samples(sample_id), control_id bigint references controls(control_id), invoice_match text, customer_match text, guest_match text, date_match text, taxable_amount_match text, cgst_match text, sgst_match text, igst_match text, total_amount_match text, payment_match text, bank_match text, overall_result text, auditor_review_status text default 'PENDING', auditor_comment text, auditor_conclusion text, created_at timestamptz default now());
create table if not exists exceptions (exception_id bigint generated by default as identity primary key, test_id bigint references control_tests(test_id), sample_id bigint references audit_samples(sample_id), transaction_id bigint references sales_transactions(transaction_id), invoice_number text, exception_type text, severity text, description text, financial_impact numeric(18,2), status text default 'OPEN', resolution text, auditor_comment text, created_at timestamptz default now());
create index if not exists idx_sales_invoice on sales_transactions(invoice_id);
create index if not exists idx_sales_customer on sales_transactions(customer_id);
create index if not exists idx_sales_date on sales_transactions(transaction_date);
create index if not exists idx_invoices_number on invoices(invoice_number);
create index if not exists idx_payments_transaction on payments(transaction_id);
create index if not exists idx_payments_reference on payments(payment_reference);
create index if not exists idx_bank_reference on bank_transactions(reference);
create index if not exists idx_bank_date on bank_transactions(transaction_date);
create index if not exists idx_samples_transaction on audit_samples(transaction_id);
create index if not exists idx_tests_sample on control_tests(sample_id);
create index if not exists idx_exceptions_sample on exceptions(sample_id);
create index if not exists idx_exceptions_status on exceptions(status);
